it('lets you carry on playing from the same state after an incomplete replay ends', async () => {
  // Snapshot the rendered well so we can compare two games cell by cell
  const getWell = (game: ReturnType<typeof render>) =>
    Array.from(game.container.querySelectorAll('table tr'), row =>
      Array.from(row.querySelectorAll('td'), td => td.getAttribute('class'))
    )

  const game = renderGame()

  // Replay is an incomplete game: a single "down" move
  const prompt = sinon.stub(window, 'prompt')
  prompt.returns('D')
  await user.click(screen.getByTestId('replay-button'))
  assert.deepEqual(prompt.getCalls().map(call => call.args), [
    ['Paste replay string...']
  ])
  prompt.restore()

  // Play the single replay step
  await advanceReplaySteps(2)

  // Not stuck in replay mode; the user can carry on playing
  assert.equal(screen.queryAllByTestId('bottom').length, 0)
  assert.equal(screen.queryAllByTestId('down').length, 1)

  // Keep playing from the post-replay state: two more "down" moves
  await user.click(screen.getByTestId('down'))
  await user.click(screen.getByTestId('down'))
  const continuedWell = getWell(game)

  game.unmount()

  // Compare against a game played manually from the start. The same three
  // "down" moves (one from the replay, two by hand) must reach the exact
  // same well, proving the replay handed over its state rather than restarting.
  const manualGame = renderGame()
  await user.click(screen.getByTestId('start-button'))
  await user.click(screen.getByTestId('down'))
  await user.click(screen.getByTestId('down'))
  await user.click(screen.getByTestId('down'))
  const manualWell = getWell(manualGame)

  assert.deepEqual(continuedWell, manualWell)
  manualGame.unmount()
})

